10	    --navy: #1B2A4A; --red: #E74C3C; --green: #2ECC71; --blue: #3498DB; --orange: #E67E22;
11	    --white: #ECF0F1; --gray: #7F8C8D;
12	  }
13	  * { margin:0; padding:0; box-sizing:border-box; }
14	  body { background:var(--bg); color:var(--white); font-family:'Segoe UI',Inter,system-ui,-apple-system,sans-serif; line-height:1.6; }
15	  .container { max-width:1200px; margin:0 auto; padding:24px; }
16	
17	  /* Header */
18	  .report-header { text-align:center; padding:48px 24px 36px; border-bottom:1px solid #263545; margin-bottom:32px; }
19	  .report-header h1 { font-size:2.2em; color:var(--gold); font-weight:700; letter-spacing:-0.5px; margin-bottom:8px; }
20	  .report-header .subtitle { color:var(--gray); font-size:1.05em; max-width:720px; margin:0 auto 16px; }
21	  .report-header .meta { display:flex; justify-content:center; gap:24px; color:var(--gray); font-size:0.85em; flex-wrap:wrap; }
22	  .report-header .meta span { display:flex; align-items:center; gap:6px; }
23	
24	  /* KPI strip */
25	  .kpi-strip { display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:16px; margin-bottom:36px; }
