27	  .kpi-card:hover { border-color:var(--gold); }
28	  .kpi-card .kpi-label { color:var(--gray); font-size:0.78em; text-transform:uppercase; letter-spacing:1px; margin-bottom:6px; }
29	  .kpi-card .kpi-value { color:var(--gold); font-size:1.7em; font-weight:700; }
30	  .kpi-card .kpi-sub { color:var(--gray); font-size:0.75em; margin-top:4px; }
31	
32	  /* Section */
33	  .section { margin-bottom:48px; }
34	  .section-header { display:flex; align-items:center; gap:12px; margin-bottom:20px; padding-bottom:12px; border-bottom:1px solid #263545; }
35	  .section-num { background:var(--gold-d); color:var(--bg); font-weight:700; font-size:0.85em; width:28px; height:28px; border-radius:50%; display:flex; align-items:center; justify-content:center; }
36	  .section-header h2 { color:var(--gold); font-size:1.35em; font-weight:600; }
37	  .section p { color:#b0bec5; margin-bottom:14px; font-size:0.95em; }
38	  .section p strong { color:var(--white); }
39	
40	  /* Charts */
41	  .chart-container { margin:24px 0; text-align:center; }
42	  .chart-container img { max-width:100%; border-radius:8px; border:1px solid #263545; }
43	  .chart-caption { color:var(--gray); font-size:0.8em; font-style:italic; margin-top:8px; }
44	
45	  /* Tables */
46	  .data-table { width:100%; border-collapse:collapse; margin:16px 0; font-size:0.85em; }
47	  .data-table th { background:#1a2f45; color:var(--gold); padding:10px 12px; text-align:left; border-bottom:2px solid #263545; font-weight:600; white-space:nowrap; }
48	  .data-table td { padding:8px 12px; border-bottom:1px solid #1a2a3a; }
49	  .data-table tr:hover { background:#1a2a3a; }
50	  .table-wrapper { overflow-x:auto; border-radius:8px; border:1px solid #263545; }

